package config

import (
	"errors"
	"fmt"
	"os"
)

// newContextConfig returns the configuration of a freshly created context:
// the defaults, with no monitors and no forge URL.
func newContextConfig() *Config {
	cfg := Default()
	cfg.Status.Components = []ComponentConfig{}
	cfg.Forge.URL = ""
	return cfg
}

// createContextFile creates path exclusively (it fails with os.ErrExist when
// the file is there) and writes cfg with the commented price example. A file
// whose write failed is removed so no truncated config is left behind.
func createContextFile(path string, cfg *Config) error {
	data, err := marshalContext(cfg, true)
	if err != nil {
		return err
	}
	if err := EnsureConfigDir(); err != nil {
		return err
	}
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	if _, err := f.Write(data); err != nil {
		_ = f.Close()
		_ = os.Remove(path)
		return err
	}
	if err := f.Close(); err != nil {
		_ = os.Remove(path)
		return err
	}
	return nil
}

// CreateContext creates a new context with a default configuration
// Empty monitors, empty GitLab URL, other values default. The file carries the
// commented price example and is never overwritten.
func CreateContext(contextName string) error {
	if err := ValidateNewContextName(contextName); err != nil {
		return err
	}
	path, err := GetContextPath(contextName)
	if err != nil {
		return err
	}
	err = createContextFile(path, newContextConfig())
	if errors.Is(err, os.ErrExist) {
		return fmt.Errorf("context '%s' already exists: %w", contextName, ErrContextExists)
	}
	return err
}

// WriteNewContext writes cfg as the context contextName, with the commented
// price example, replacing any file already there.
func WriteNewContext(cfg *Config, contextName string) error {
	if err := ValidateContextName(contextName); err != nil {
		return err
	}
	path, err := GetContextPath(contextName)
	if err != nil {
		return err
	}
	data, err := marshalContext(cfg, true)
	if err != nil {
		return err
	}
	if err := EnsureConfigDir(); err != nil {
		return err
	}
	return os.WriteFile(path, data, 0600)
}

// CreateDefaultContextIfMissing creates config.yaml when the current context is
// "default" and the file is absent, and reports whether it did. An existing
// config.yaml, even an invalid one, is neither read nor rewritten. The
// creation is exclusive, so of several concurrent callers only one gets true.
func CreateDefaultContextIfMissing() (bool, error) {
	if CurrentContextName() != "default" {
		return false, nil
	}
	path, err := GetContextPath("default")
	if err != nil {
		return false, err
	}
	err = createContextFile(path, newContextConfig())
	switch {
	case err == nil:
		return true, nil
	case errors.Is(err, os.ErrExist):
		return false, nil
	default:
		return false, err
	}
}
package config

import (
	"strings"

	"gopkg.in/yaml.v3"
)

// examplePricesMarker is the first line of ExamplePricesBlock. Files on disk
// are recognized by it, so it must never change.
const examplePricesMarker = "# Optional: price table for the :agent-usage cost estimate."

// ExamplePricesBlock is the commented agent_usage.prices example appended to a
// context file while it holds no price. Every line is a comment.
const ExamplePricesBlock = examplePricesMarker + `
# Uncomment, then replace the model name and the numbers with your own.
# Rates are in USD per million tokens; take the current ones from your
# provider's price page. The numbers below only show the shape, they are not
# real prices.
#
# agent_usage:
#   prices:
#     claude-example-model:
#       input: 3
#       output: 15
#       cache_write_5m: 3.75
#       cache_write_1h: 6
#       cache_read: 0.3
`

// carriesExampleBlock reports whether data holds a whole line equal to the
// example marker. Trailing spaces, tabs and \r are ignored; leading ones are not.
func carriesExampleBlock(data []byte) bool {
	for _, line := range strings.Split(string(data), "\n") {
		if strings.TrimRight(line, " \t\r") == examplePricesMarker {
			return true
		}
	}
	return false
}

// marshalContext encodes cfg as YAML. With withExample, the commented price
// example is appended, but only when cfg holds no price entry.
func marshalContext(cfg *Config, withExample bool) ([]byte, error) {
	data, err := yaml.Marshal(cfg)
	if err != nil {
		return nil, err
	}
	if withExample && len(cfg.AgentUsage.Prices) == 0 {
		data = append(data, "\n"+ExamplePricesBlock...)
	}
	return data, nil
}

